# Writes research/reviews/canon-4-round3.json from the round's raw findings, each confirmed finding's outcome (the fix, its
# check and the revert result from ../revert3-results.json) and the run's figures (rec3-figs.json).
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
P4 = os.path.join(HERE, '..', '..')
raw = json.load(open(os.path.join(P4, 'round3-raw.json')))
rv = json.load(open(os.path.join(HERE, '..', 'revert3-results.json')))
F = json.load(open(os.path.join(HERE, 'rec3-figs.json')))
def lab(x):
    p = x.split(': ')
    return ': '.join(p[:2]) if p[0].startswith('review round') else p[0]
def res(*names):
    out = []
    for n in names:
        r = rv[n]; fails = []
        for part, lst in r.items():
            if part.startswith('page-'): fails += ["shots.js '" + lab(x) + "'" for x in lst]
            elif part == 'powers': fails += ['powers.js ' + x.split(':')[0].replace('FAIL ', '') for x in lst]
        out.append(n + ' -> ' + ('; '.join(dict.fromkeys(fails)) if fails else 'NO CHECK FAILED'))
    return 'Reverted in a scratch copy (scratchpad pr4/r3fix/js/revert3.py): ' + ' | '.join(out) + '.'
