lenses = []
n = conf = 0; refuted = []
for L in raw:
    fs = []
    for f in L['findings']:
        n += 1
        if f['verdict']['real']: conf += 1
        else: refuted.append(f['id'])
        g = dict(f); g['outcome'] = O[f['id']]; fs.append(g)
    lenses.append({'lens': L['lens'], 'verified_ok': L.get('verified_ok', []), 'findings': fs})
